package com.example.bookstore.controller;
import com.example.bookstore.dto.*; import com.example.bookstore.service.BookService; import jakarta.validation.Valid; import org.springframework.data.domain.*; import org.springframework.data.web.PageableDefault; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/books") public class BookController { private final BookService service; public BookController(BookService service){this.service=service;} @PostMapping ResponseEntity<BookResponse> create(@Valid @RequestBody BookRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(service.create(r));} @GetMapping Page<BookResponse> all(@RequestParam(required=false) String keyword,@RequestParam(required=false) Long authorId,@RequestParam(required=false) Long categoryId,@PageableDefault(size=10,sort="title") Pageable pageable){return service.findAll(keyword,authorId,categoryId,pageable);} @GetMapping("/{id}") BookResponse one(@PathVariable Long id){return BookResponse.from(service.get(id));} @PutMapping("/{id}") BookResponse update(@PathVariable Long id,@Valid @RequestBody BookRequest r){return service.update(id,r);} @DeleteMapping("/{id}") ResponseEntity<Void> delete(@PathVariable Long id){service.delete(id);return ResponseEntity.noContent().build();} }
